import 'package:benchmark_harness/benchmark_harness.dart';
import 'package:cell_flow/cell_flow.dart';

class FromStreamSync extends AsyncBenchmarkBase {
  FromStreamSync() : super('flow: fromStream sync');
  int done = 0;

  @override
  Future<void> run() async {
    // One-shot per iteration: the stream bridge completes after its first
    // trigger, so a fresh handle is materialized each run.
    done = 0;
    final h = Flow.fromStream<int>(Cell.ingress<int>().cell,
        stream: Stream.fromIterable(List.generate(100, (i) => i)));
    Cell.observe(source: h.cell, effect: (_) => done++);
    h.emit(0);
    while (done < 100) {
      await Future<void>.delayed(Duration.zero);
    }
  }
}

class FromStreamDeferred extends AsyncBenchmarkBase {
  FromStreamDeferred() : super('flow: deferStream');
  late final FlowHandle h = Flow.deferStream<int>(Cell.ingress<int>().cell,
      create: () => Stream.fromIterable(List.generate(100, (i) => i)));

  @override
  Future<void> run() async {
    h.emit(0);
    await Future<void>.delayed(const Duration(milliseconds: 20));
  }
}

class RawStreamControl extends AsyncBenchmarkBase {
  RawStreamControl() : super('flow: [control] raw Stream listen');
  int done = 0;

  @override
  Future<void> run() async {
    done = 0;
    Stream.fromIterable(List.generate(100, (i) => i)).listen((_) => done++);
    while (done < 100) {
      await Future<void>.delayed(Duration.zero);
    }
  }
}

